// Η ΤΙΜΗ ΣΤΟ ΣΤΟΜΑ ΤΟΥ ΒΟΗΘΟΥ ΕΙΝΑΙ Η ΤΙΜΗ ΣΤΗΝ ΟΘΟΝΗ. Ο τοπικός μορφοποιητής
// έκοβε τα δεκαδικά και κολλούσε το ευρώ («11€»), οπότε ο βοηθός ανέφερε την
// συνδρομή αλλιώς από κάθε άλλο σημείο της εφαρμογής («11,00 €»).
const eur = fe;
const P_SOLO = PLANS.solo, P_OWNER = PLANS.owner, P_AGENCY = PLANS.agency, P_OFFICE = PLANS.office;

/**
 * Οι προτιμήσεις του χρήστη για τη ΣΥΜΠΕΡΙΦΟΡΑ, όχι για την ταυτότητα.
 * Το όνομα δεν είναι πια ρύθμιση: είναι το προϊόν.
 */
export interface AssistantPrefs {
  memory: boolean;    // να θυμάται τις συζητήσεις
  compare: boolean;   // να συγκρίνει μεταξύ ακινήτων
  formal: boolean;    // true = πληθυντικός ευγενείας (εσείς), false = ενικός (εσύ)
}

export const DEFAULT_PREFS: AssistantPrefs = { memory: true, compare: false, formal: false };

